	title 'QD Regions           GS ROM 3.0'*****************************************************************			   **              REGIONS		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	blanks off	string asis		include 'all.macros'	include '::sys.equs.asm'	MACRO&lab	BumpLongBy2 &adr&lab	lda &adr	ldx &adr+2	inc a	bne @1	inx@1	inc a	bne @2	inx@2	sta &adr	stx &adr+2	MEND	MACRO&lab	MoveLong &From,&To&lab	lda &From	sta &To	lda &From+2	sta &To+2	MEND	MACRO&lab	IncLong &adr&lab	inc &adr	bne @1	inc &adr+2@1	mend	include ':QDEquates:qd.data.asm'		INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:rect.equs'	INCLUDE ':QDEquates:slab.equs';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyEC12	IMPORT BusyEC4	IMPORT BusyEC8	IMPORT BusyErr0	IMPORT BusyErr12	IMPORT BusyErr4	IMPORT BusyErr8	IMPORT CheckPenVis	IMPORT CommonSlabSetup	IMPORT NextPatSlice	IMPORT QDStart	IMPORT RgnSave	IMPORT SetFirstDestRef	IMPORT SetNextDestRef	IMPORT SpecialNewHandle	IMPORT TestGPs;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY CallRgn	ENTRY ClipToRgnA	ENTRY ConTable320	ENTRY ConTable640	ENTRY DeRefA	ENTRY DeRefB	ENTRY DeRefC	ENTRY DerefHandle	ENTRY Expand320	ENTRY Expand640	ENTRY FrRgn	ENTRY GetNextV	ENTRY GetStateInfo	ENTRY InitDataPtr	ENTRY InitRgnUp	ENTRY InvertBuf	ENTRY JoinRgn	ENTRY JoinSetUp	ENTRY LeftBitMask	ENTRY LineSetup	ENTRY RectScanInvert	ENTRY ResizeA	ENTRY ResizeB	ENTRY ResizeHandle	ENTRY RightBitMask	ENTRY SpecialSlab	ENTRY UnlockA	ENTRY UnlockB	ENTRY UnlockC	ENTRY UnlockHandle	ENTRY ValidRgnRect	ENTRY VisToRgnB	ENTRY ZeroRgnA	ENTRY ZeroScanBuf	ENTRY UnlockBufferHandle;                copy regions/draw****************************************************************** FrameRgn   (r : rgnHandle)******************************************************************	EXPORT FrameRgnFrameRgn	PROC*              using PicInfo	ldx #FrameVerb	bra JoinRgn	ENDP****************************************************************** PaintRgn     (r :	rgnHandle)******************************************************************	EXPORT PaintRgnPaintRgn	PROC*              using PicInfo	ldx #PaintVerb	bra JoinRgn	ENDP****************************************************************** EraseRgn     (r :	rgnHandle)******************************************************************	EXPORT EraseRgnEraseRgn	PROC*              using PicInfo	ldx #EraseVerb	bra JoinRgn	ENDP****************************************************************** InvertRgn    (r :	rgnHandle)******************************************************************	EXPORT InvertRgnInvertRgn	PROC*              using PicInfo	ldx #InvertVerb; let this one fall	right into JoinRGN	ENDP****************************************************************** JoinRgn** This is common routine called by Frame, Paint, Invert and* erase Rgn.  The draw verb is passed in the x-register*****************************************************************	EXPORT JoinRgnJoinRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RHandle	equ RTL2+3	jsr QDStart	; x is preserved	lda RHandle,s	; put rgn handle on	zp	sta RgnHandleC	lda RHandle+2,s	sta RgnHandleC+2	jsl CallRgn	; call using draw verb in x	tax	; error returned in	x	jmp BusyErr4	ENDP****************************************************************** FillRgn      (r :	rgnHandle; p : pattern)******************************************************************	EXPORT FillRgnFillRgn	PROC*              using PicInfo*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPtr	equ RTL2+3RPtr	equ PPtr+4	jsr QDStart	jsl UserPat2ZP	lda RPtr,s	sta RgnHandleC	lda RPtr+2,s	sta RgnHandleC+2	ldx #FillVerb	jsl CallRgn	tax	jmp BusyErr8	ENDP****************************************************************** CallRgn ** This routine is jumped (or branched) to by the* entry points after the graf verb is loaded into the* x register.** Zero page is already switched in by the time it gets here.*****************************************************************	EXPORT CallRgnCallRgn	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	stx DrawVerb	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdRgnUseLocal	phb	; put extra byte on	stack	ldy #o_stdrgn	; get adr of new rgn routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** StdRgn** Common region routine that is central	point for* all region drawing routines.** When control gets	here, all inputs are on zero page.*       TheRgn is kept at RgnC.*       ThePat (if any) is in FillPat*       WhatToDo is	in DrawVerb*****************************************************************	EXPORT iStdRgniStdRgn	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	EXPORT CommonFastRgn;---------------------------------------------------------------	lda #RgnNoun	sta DrawNoun	; put on zp too!!!	jsl PutPictStuff	; inputs on zp and in a-reg	bcc NoPicErr	rtl	; return the errorNoPicErr	lda DrawVerb	; put verb in a	bne CommonFastRgn	jsr RgnSave	; does this contribute to region def	bcc FrRgn	; no, so frame it	jsl PutRgn	; yes, so call putrgn 	bcc FrRgn	; if no error go on	and frame it.	rtl	; return the error;---------------------------------------------------------------CommonFastRgn	jsr  DeRefC	;check to see if the region is rectangular	lda  [RgnPtrC]	;..if it's not, then call CommonSlabSetup	cmp  #10	bne  @notRectangle	ldy  #2	;we are rectangular so copy the bounding rect to direct page	lda  [RgnPtrC],y	sta  Y1	ldy  #4	lda  [RgnPtrC],y	sta  X1	ldy  #6	lda  [RgnPtrC],y	sta  Y2	ldy  #8	lda  [RgnPtrC],y	sta  X2	jsr  UnlockC	;unlock the region handle	lda #RectNoun	sta DrawNoun@notRectangle	jmp CommonSlabSetup;---------------------------------------------------------------	ENDP****************************************************************** PRgn, FRgn, IRgn,	ERgn*****************************************************************	EXPORT PRgnPRgn	PROC	ENDP	EXPORT FRgnFRgn	PROC	ENDP	EXPORT IRgnIRgn	PROC	ENDP	EXPORT ERgnERgn	PROC*              using PicInfo	lda #RgnNoun	sta DrawNoun	bra  CommonFastRgn	ENDP****************************************************************** FrRgn** Modifications:**    April 13, 1986	   First I was not unlocking the region	to*	   frame when it was not a rectangle.**	   Finally I was disposing of the temp region*	   wrong (pushed the handle on the stack*	   backwards).*****************************************************************	EXPORT FrRgnFrRgn	PROC*              using CoreDATA*              using E0Vectors	jsr CheckPenVis	; don't come back unless visible	jsr DeRefC	; look at the region and see if it	lda [RgnPtrC]	; is rectangular?	cmp #10	bne NotRect	ldy #2	; yes it is so copy	the bounds rect	lda [RgnPtrC],y	; from the region to rect on zero page	sta Y1	iny	iny	lda [RgnPtrC],y	sta X1	iny	iny	lda [RgnPtrC],y	sta Y2	iny	iny	lda [RgnPtrC],y	sta X2	jsr UnlockC	; now free the region	jml v_FrRect	; jump to internal frame rect routine*		; through vector in	bank E0.NotRect		; 	jsr UnlockC	; don't need it locked any more	ldy #o_pnSize	; get the pen size on the stack	lda [PortRef],y	pha	iny	iny	lda [PortRef],y	pha	pei RgnHandleC+2	; put rgnhandle c on stack	pei RgnHandleC	PushLong #0	; put handle to new	region on stack	_NewRgn	phd	tsc	; make stack into zero page	tcdOrigDirect	equ 1TempRgn	equ 3	; now these are the	zero pageUserRgn	equ 7	; vars I'll deal with.PenX	equ 11PenY	equ 13	pei UserRgn+2	; first TempRgn := UserRgn	pei UserRgn	pei TempRgn+2	pei TempRgn	_CopyRgn	pei TempRgn+2	; TempRgn :=InsetRgn(TempRgn,Penx,PenY)	pei TempRgn	pei PenX	pei PenY	_InsetRgn	pei UserRgn+2	; TempRgn := UserRgn - TempRgn	pei UserRgn	pei TempRgn+2	pei TempRgn	pei TempRgn+2	pei TempRgn	_DiffRgn	lda TempRgn	ldx TempRgn+2	pld	; restore zp	ply	; clear off stack without	ply	; hurting a reg	ply	ply	ply	ply	sta RgnHandleC	; put the handle to	temp rgn in	stx RgnHandleC+2	; RgnHandleC	jsl PRgn	; call PRgn	pei RgnHandleC+2	; Noe dispose it	pei RgnHandleC	_DisposeRgn	lda #0	clc	rtl	ENDP****************************************************************** DrawRgn** Draws the specified region using the pattern kept in* FillPat, using the mode kept in FillMode*****************************************************************	EXPORT DrawRgnDrawRgn	PROC*              using E0Vectors	phb	; save the bank reg	here	jsl Init3Regions	jsl SetSlabAdr	; sets up the slab adr on zp	jsl XSetup	jsr SetFirstDestRefRgnLoop		; 	jsr NextPatSlice	jsl Seek3Regions	jsl ToSlab	lda CurrentY	inc a	cmp Y2	bpl TheEnd	; hey moron, signed	compare 28 Mar 86	sta CurrentY	jsr SetNextDestRef	bra RgnLoopTheEnd	plb	; restore bank	rtl	ENDP****************************************************************** GetBoundsC** Gets the bounds rect of rgn c and puts it in MinRect*****************************************************************	EXPORT GetBoundsCGetBoundsC	PROC	ldy #2	ldx #0Loop	lda [RgnPtrC],y	sta MinRect,x	iny	iny	inx	inx	cpy #10	bcc Loop	rts	ENDP****************************************************************** NewRgn*****************************************************************	EXPORT NewRgnNewRgn	PROC*              using RegionDataOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ResultHandle	equ RTL2+3	jsr QDStart	lda #10	; size	ldx UserID	ldy #RgnAttributes	jsr SpecialNewHandle	bcs Error	stx RgnHandleA	sty RgnHandleA+2	txa	sta ResultHandle,s	tya	sta ResultHandle+2,s	jsr DeRefA	lda #10	; set region to null region	sta [RgnPtrA]	; size is 10	jsr ZeroRgnA	jsr UnlockA	lda #0Error	tax	; put error in x	jmp BusyErr0	; quit	ENDP****************************************************************** DisposeRgn*******************************************************************	EXPORT DisposeRgnDisposeRgn	PROC*              using RegionDataOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheHandle	equ RTL2+3	jsr QDStart	lda TheHandle,s	tax	lda TheHandle+2,s	pha	phx	_DisposeHandle	tax	; propagate any error that may	jmp BusyErr4	; occur	ENDP****************************************************************** SetEmptyRgn** Sets the region to the empty region.	The must already be* allocated*****************************************************************	EXPORT SetEmptyRgnSetEmptyRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RgnHandle	equ RTL2+3	jsr QDStart	lda RgnHandle,s	sta RgnHandleA	lda RgnHandle+2,s	sta RgnHandleA+2	jsr DeRefA	lda #10	cmp [RgnPtrA]	beq SizeOK	jsr ResizeA	bcs errorSizeOK	jsr ZeroRgnA	jsr UnlockA	jmp BusyEC4error	tax	jmp BusyErr4	ENDP****************************************************************** ZeroRgnA** An internal routine to zero the bounding box of the region* pointed to by RgnPtrA.** A & Y are lost, X	is unchanged.*****************************************************************	EXPORT ZeroRgnAZeroRgnA	PROC	ldy #2	lda #0Loop	sta [RgnPtrA],y	iny	iny	cpy #10	bcc Loop	rts	ENDP****************************************************************** SetRectRgn*              RgnHandle : handle*              Left, Top, Right, Bottom	: integer** This takes the region pointed described by RgnHandle and* sets it to a rectangular region described by four integers** If the rectangle is not valid, then the region is set to* the zero rect ([0,0,0,0]).*****************************************************************	EXPORT SetRectRgnSetRectRgn	PROC*              using RegionDataOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Bottom	equ RTL2+3Right	equ Bottom+2Top	equ Right+2Left	equ Top+2RgnHandle	equ Left+2	jsr QDStart	lda RgnHandle,s	; get the handle and deref it	sta RgnHandleA	lda RgnHandle+2,s	sta RgnHandleA+2	jsr DeRefA	lda #10	cmp [RgnPtrA]	beq SizeOK	jsr ResizeA	bcs errorSizeOk	ldy #2	lda Top,s	sta [RgnPtrA],y	iny	iny	lda Left,s	sta [RgnPtrA],y	iny	iny	lda Bottom,s	sta [RgnPtrA],y	iny	iny	lda Right,s	sta [RgnPtrA],y	jsr ValidRgnRectAllDone	jsr UnlockA	jmp BusyEC12error	tax	jmp BusyErr12	ENDP****************************************************************** ValidRgnRect** This is an internal routine to make sure that the contents* of region A's bounding box is valid.  If the contents are* not valid, they are reset to zero.*****************************************************************	EXPORT ValidRgnRectValidRgnRect	PROC	ldy #2	lda [RgnPtrA],y	ldy #6	cmp [RgnPtrA],y	bpl ZeroRect	ldy #4	lda [RgnPtrA],y	ldy #8	cmp [RgnPtrA],y	bpl ZeroRectAllDone	rtsZeroRect	jsr ZeroRgnA	bra AllDone	ENDP****************************************************************** RectRgn*              RgnHandle : handle*              RectPtr   : ptr** This takes the region pointed described by RgnHandle and* sets it to a rectangular region described by the rectangle.** If the rectangle is not valid, then the region is set to* the zero rect ([0,0,0,0]).*****************************************************************	EXPORT RectRgnRectRgn	PROC*              using RegionDataOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RectPtr	equ RTL2+3RgnHandle	equ RectPtr+4	jsr QDStart	lda RgnHandle,s	sta RgnHandleA	lda RgnHandle+2,s	sta RgnHandleA+2	jsr DeRefA	lda #10	cmp [RgnPtrA]	beq SizeOK	jsr ResizeA	bcs errorSizeOk	lda RectPtr,s	sta Temp	lda RectPtr+2,s	sta Temp+2	ldy #0	; copy the rect to theLoop	lda [Temp],y	; region's bounding box	iny	iny	sta [RgnPtrA],y	cpy #8	bcc Loop	jsr ValidRgnRect	; now make sure its	validAllDone	jsr UnlockA	jmp BusyEC8error	tax	jmp BusyErr8	ENDP****************************************************************** CopyRgn*              SrcRgn : Handle*              DestRgn : Handle** ChangeHistory** 26 Oct 88	Steven Glass** Two changes.  First I use the memmover routine in ROM* instead of _blockmove.  Second, I look for the simple* case where there are only ten bytes to move and do* them in line.*****************************************************************CopyRgn	PROC EXPORTOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3DestHandle	equ RTL2+3SrcHandle	equ DestHandle+4	jsr QDStart	lda SrcHandle,s	; dereference the src	sta RgnHandleA	lda SrcHandle+2,s	sta RgnHandleA+2	jsr DeRefA	lda DestHandle,s	; dereference the dest	sta RgnHandleB	lda DestHandle+2,s	sta RgnHandleB+2	jsr DeRefB	lda [RgnPtrA]	; get source size	cmp [RgnPtrB]	; compare to dest size	beq SizeOK	jsr ResizeB	bcs errorSizeOk	lda [RgnPtrA]	; is this a simple rect region?	cmp #10	bne NotSimple	sta [RgnPtrB]	; move it inline.	ldy #2	lda [RgnPtrA],y	sta [RgnPtrB],y	ldy #4	lda [RgnPtrA],y	sta [RgnPtrB],y	ldy #6	lda [RgnPtrA],y	sta [RgnPtrB],y	ldy #8	lda [RgnPtrA],y	sta [RgnPtrB],y	bra AllDoneNotSimple		; move it the hard way.	pei RgnPtrA+2	; Src ptr	pei RgnPtrA	pei RgnPtrB+2	; dest ptr	pei RgnPtrB	PushWord #0	lda [RgnPtrA]	pha	; how many to move	PushWord #BlockMoveCommandWord	jsl ToMemMoverAllDone	jsr UnlockA	jsr UnlockB	jmp BusyEC8error	tax	jmp BusyErr8	ENDP****************************************************************** EqualRgn**          Rgn1  : handle*          Rgn2  : handle** Returns true if the two regions are identical.*****************************************************************	EXPORT EqualRgnEqualRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Rgn1	equ RTL2+3Rgn2	equ Rgn1+4Result	equ Rgn2+4	jsr QDStart	lda Rgn1,s	; dereference one	sta RgnHandleA	lda Rgn1+2,s	sta RgnHandleA+2	jsr DeRefA	lda Rgn2,s	; dereference the other	sta RgnHandleB	lda Rgn2+2,s	sta RgnHandleB+2	jsr DeRefB	lda [RgnPtrA]	; get size of one	cmp [RgnPtrB]	; compare to size of other	bne NotEqual	tay	dey	deyLoop	lda [RgnPtrA],y	cmp [RgnPtrB],y	bne NotEqual	dey	dey	bne Loop	lda #TrueAllDone	sta Result,s	jsr UnlockA	jsr UnlockB	jmp BusyEC8NotEqual	lda #False	bra AllDone	ENDP****************************************************************** EmptyRgn**          Rgn  : handle** Returns true if the region is rectangular and its bounding* box is set an invalid rectangle (top greater than or equal to* bottom or left greater than or equal to right)** Modified 4 apr 86	SEG**    This used to return true only if bounding box was set to*    all zeros.  This was not good enough since regions can*    be empty and not set this way.*****************************************************************	EXPORT EmptyRgnEmptyRgn	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Rgn	equ RTL2+3Result	equ Rgn+4	jsr QDStart	lda Rgn,s	; dereference the rgn	sta RgnHandleA	lda Rgn+2,s	sta RgnHandleA+2	jsr DeRefA	lda [RgnPtrA]	; get source size	cmp #10	bne NotEmpty	ldy #2	lda [RgnPtrA],y	ldy #6	cmp [RgnPtrA],y	bpl YesZero	ldy #4	lda [RgnPtrA],y	ldy #8	cmp [RgnPtrA],y	bmi NotEmptyYesZero	lda #TrueAllDone	sta Result,s	jsr UnlockA	jmp BusyEC4NotEmpty	lda #False	bra AllDone	ENDP****************************************************************** DeRefAndLock** This takes a handle in the A & X registers and dereferences* and locks it.** The result ptr is	returned in a & x.** The location TEMP	on zero page is trashed as is Y****************************************************************	EXPORT DeRefAndLockDeRefAndLock	PROC	EXPORT DeRefAndLocDeRefAndLoc		;       	sta Temp	stx Temp+2	ldy #4	lda [Temp],y	ora #$8000	sta [Temp],y	dey	dey	lda [Temp],y	tax	lda [Temp]	rts	ENDP****************************************************************** Unlock Mem** This is used after a handle has been locked to release it.** Like DeRefAndLock, the handle is passed in the A & X registers.*****************************************************************	EXPORT UnlockMemUnlockMem	PROC	sta Temp	stx Temp+2	ldy #4	lda [Temp],y	and #$7FFF	sta [Temp],y	rts	ENDP****************************************************************** DeRefA*****************************************************************	EXPORT DeRefADeRefA	PROC	ldy #4	; lock it	lda [RgnHandleA],y	ora #$8000	sta [RgnHandleA],y	lda [RgnHandleA]	; deref it.	sta RgnPtrA	ldy #2	lda [RgnHandleA],y	sta RgnPtrA+2	rts	ENDP****************************************************************** UnlockA*****************************************************************	EXPORT UnlockAUnlockA	PROC	ldy #4	; unlock it	lda [RgnHandleA],y	and #$7FFF	sta [RgnHandleA],y	rts	ENDP****************************************************************** DeRefB*****************************************************************	EXPORT DeRefBDeRefB	PROC	ldy #4	; lock it	lda [RgnHandleB],y	ora #$8000	sta [RgnHandleB],y	lda [RgnHandleB]	; deref it.	sta RgnPtrB	ldy #2	lda [RgnHandleB],y	sta RgnPtrB+2	rts	ENDP****************************************************************** UnlockB*****************************************************************	EXPORT UnlockBUnlockB	PROC	ldy #4	; unlock it	lda [RgnHandleB],y	and #$7FFF	sta [RgnHandleB],y	rts	ENDP****************************************************************** DeRefC*****************************************************************	EXPORT DeRefCDeRefC	PROC	ldy #4	; lock it	lda [RgnHandleC],y	ora #$8000	sta [RgnHandleC],y	lda [RgnHandleC]	; deref it.	sta RgnPtrC	ldy #2	lda [RgnHandleC],y	sta RgnPtrC+2	rts	ENDP****************************************************************** UnlockC*****************************************************************	EXPORT UnlockCUnlockC	PROC	ldy #4	; unlock it	lda [RgnHandleC],y	and #$7FFF	sta [RgnHandleC],y	rts	ENDP****************************************************************** ResizeA*****************************************************************	EXPORT ResizeAResizeA	PROC	ldx #RgnHandleA	jsr ResizeHandle	bcs error	sta RgnPtrA	stx RgnPtrA+2	lda [RgnPtrA]error	rts	ENDP****************************************************************** ResizeB*****************************************************************	EXPORT ResizeBResizeB	PROC	ldx #RgnHandleB	jsr ResizeHandle	bcs error	sta RgnPtrB	stx RgnPtrB+2	lda [RgnPtrB]error	rts	ENDP****************************************************************** ResizeC*****************************************************************	EXPORT ResizeCResizeC	PROC	ldx #RgnHandleC	jsr ResizeHandle	bcs error	sta RgnPtrC	stx RgnPtrC+2	lda [RgnPtrC]	; get size back in aerror	rts	ENDP****************************************************************** DerefHandle*****************************************************************	EXPORT DerefHandleDerefHandle	PROC* enter with zero page offset to src in	X* sample usage:**     ldx #RgnHandleA*     jsr DerefHandle*     sta RgnPtrA*     stx RgnPtrA+2	lda 0,x	sta Temp	lda 2,x	sta Temp+2	EXPORT QuickDerefQuickDeref		;       ; enter here if Temp has handle	already* sample usage:*     jsr QuickDeref	; Temp still has handle*     sta RgnPtrA*     stx RgnPtrA+2* handle is in Temp; lock it down	ldy #4	lda [Temp],y	ora #$8000	sta [Temp],y* dereference it, leaving low word in A	and high word in X	ldy #2	lda [Temp],y	tax	lda [Temp]	rts	ENDP****************************************************************** Procedure UnlockHandle*****************************************************************	EXPORT UnlockHandleUnlockHandle	PROC* enter with zero page offset to handle	in x* Sample usage**     ldx #RgnHandleA*     jsr UnlockHandle	lda 0,x	sta Temp	lda 2,x	sta Temp+2* unlock it	ldy #4	lda [Temp],y	and #$7FFF	sta [Temp],y* leave with Temp still holding the handle so related routines* can use it	rts	ENDP****************************************************************** ResizeHandle*****************************************************************	EXPORT ResizeHandleResizeHandle	PROC* enter with pointer to handle on zero page in x* Sample usage**     lda NewHandleSize*     ldx #RgnHandleA*     jsr ResizeHandle*     sta RgnPtrA*     stx RgnPtrA+2	pha	; push size (02)	pea 0	; push 0 for high word of size (04)	pha	; push low word of size (06)	jsr UnlockHandle	; pass X as pointer* UnlockHandle leaves a copy of the handle in Temp for us.	Long word size* is still on the stack	pei Temp+2	; push handle high (08)	pei Temp	; push handle low (0A)	_SetHandleSize	; handle size is at	top of stack (02)	bcs Error	; we found an error, A & X are invalid	EXPORT NewEntryNewEntry		;       	jsr QuickDeref	; handle still in Temp, redereference it	sta Temp	; pointer is in A &	X	stx Temp+2	pla	; get size back (00)	sta [Temp]	; set size for regions, invpt buffers	lda Temp	; pointer is in A &	X	rtsError	ply	; error in A, carry	is still set (00)	ldx #$FFFF	; invalidate pointer	rts	ENDP****************************************************************** GetNewHandle*****************************************************************	EXPORT GetNewHandleGetNewHandle	PROC*              using RegionData*              using CoreData* It accepts a size	in A and an offset to the zero page handle variable* in X.  Upon return it has initialized	a new handle, dereferenced it,* and set the first	two bytes of the handle data to the length of the* handle, which is what regions and buffers want.  Because it sets the* length it assumes	the size (in A) will never be less than	2 bytes.* It puts a copy of	the new handle into	the location pointed at by X.* The dereferenced pointer is returned in A and X.	pha	; save size	phx	; save offset	ldx UserID	ldy #RgnAttributes	jsr SpecialNewHandle	bcs HandleError	; if error, clean up	stx Temp	sty Temp+2	plx	; get offset back	sty 2,x	; save high word to	real handle	ldy Temp	; get low word back	sty 0,x	; save low word to real handle* The size is still	on the stack.  This	now looks like we've just resized* a handle, so branch upwards and use the code we've already written.	bra NewEntry	; pointer will come	back in A and XHandleError	ply	; discard offset	ply	; discard size	rts	ENDP;                copy regions/setup****************************************************************** SetUpPortRegions** This is the procedure called by the object drawing routines* to dereference and lock the clip and vis regions and put* the "Fake" wideopen region into region C** 2/24/89	Mensch** Unwind the ClipToRgnA and VisToRgnB calls. total of 40 cycles.. not enough yet...*****************************************************************	EXPORT iSetUpPortRegionsiSetUpPortRegions	PROC*              using E0Vectors;	jsr ClipToRgnA;	jsr VisToRgnB	ldy #o_ClipRgn	lda [PortRef],y	sta RgnHandleA	ldy #o_ClipRgn+2	lda [PortRef],y	sta RgnHandleA+2	ldy #o_VisRgn	lda [PortRef],y	sta RgnHandleB	ldy #o_VisRgn+2	lda [PortRef],y	sta RgnHandleB+2	ldy #4	; lock it	lda [RgnHandleB],y	ora #$8000	sta [RgnHandleB],y	lda [RgnHandleA],y	ora #$8000	sta [RgnHandleA],y	lda [RgnHandleB]	; deref it.	sta RgnPtrB	ldy #2	lda [RgnHandleB],y	sta RgnPtrB+2	lda [RgnHandleA]	; deref it.	sta RgnPtrA	lda [RgnHandleA],y	sta RgnPtrA+2	jsl SetUpScanPtrs	rtl	ENDP****************************************************************** Region Freeing Routines** This is the procedure called by the object drawing routines* to unlock the clip and vis regions.*****************************************************************	EXPORT iFree3RegionsiFree3Regions	PROC	jsr UnlockC	EXPORT iFree2RegionsiFree2Regions		;       	jsr UnlockB	EXPORT iFree1RegioniFree1Region		;       	jsr UnlockA	jsl UnlockBufferHandle	rtl************************************************************iFreePortRegions	PROC Export** This unlocks region a, b and the buffer handle.**** External Refs:** Entry Points:** Change History** 25 Feb 89	Mensch** Spend a little more ROM space to save even more cycles per* qdcall. This one should save : 64 cycles and cost 25 bytes...************************************************************	ldy #4	lda [RgnHandleA],y	and #$7FFF	sta [RgnHandleA],y	lda [RgnHandleB],y	and #$7FFF	sta [RgnHandleB],y	lda [BufferHandle],y	and #$7FFF	sta [BufferHandle],y	rtl	ENDP****************************************************************** ClipToRgnA** An internal routine to copy the handle to the ClipRgn in* the current port to RgnHandleA on zero page and then to* Dereference it and lock it.*****************************************************************	EXPORT ClipToRgnAClipToRgnA	PROC*              using CoreData	ldy #o_ClipRgn	lda [PortRef],y	sta RgnHandleA	iny	iny	lda [PortRef],y	sta RgnHandleA+2	brl DeRefA;	rts	ENDP****************************************************************** VisToRgnB** An internal routine to copy the handle to the VisRgn in* the current port to RgnHandleB on zero page and then to* Dereference it and lock it.*****************************************************************	EXPORT VisToRgnBVisToRgnB	PROC*              using CoreData	ldy #o_VisRgn	lda [PortRef],y	sta RgnHandleB	iny	iny	lda [PortRef],y	sta RgnHandleB+2	brl DeRefB;	rts	ENDP****************************************************************** SetUpScanPtrs** An internal routine to set up the following pointers.**     ScanPtrA*     ScanPtrB*     ScanPtrC*     ScanMaskRef** These are obtained by dereferencing the BufferHandle and* dividing up the buffer it points to.*****************************************************************	EXPORT iSetUpScanPtrsiSetUpScanPtrs	PROC*              using RgnStateDATA	lda BufferHandle	ldx BufferHandle+2	jsr DerefAndLock	sta ScanMaskRef	stx ScanMaskRef+2	clc	adc MaxWidth	sta ScanPtrA; Changed	bcc @1	inx@1	stx ScanPtrA+2; Saves 2 bytes and 4 cycles;	lda ScanMaskRef+2;	adc #0;	sta ScanPtrA+2	tay	; save <A> for a second...	lda MaxWidth	lsr a	pha	; Save this on the stack for a second...	tya	; get ScanPtrA back in <A> and <X>; <A><X> contain ScanPtrA	clc	adc 1,s	; add maxWidth/2	sta ScanPtrB	bcc @2	inx@2	stx ScanPtrB+2; <A><X> contain ScanPtrB	clc	adc 1,s	; add maxWidth/2	sta ScanPtrC	bcc @3	inx@3	stx ScanPtrC+2; <A><X> contain ScanPtrC	clc	adc 1,s	sta StatePtrA	bcc @4	inx@4	stx StatePtrA+2; <A><X> contain StatePtrA	clc	adc #StateRecSize	sta StatePtrB	bcc @5	inx@5	stx StatePtrB+2; <A><X> contains StatePtrB	clc	adc #StateRecSize	sta StatePtrC	bcc @6	inx@6	stx StatePtrC+2	pla	; strip off MaxWidth/2	rtl	ENDP****************************************************************** UnlockBufferHandle******************************************************************	EXPORT UnlockBufferHandleUnlockBufferHandle	PROC	lda BufferHandle	ldx BufferHandle+2	jsr UnlockMem	rtl	ENDP;                COPY regions/toplevel****************************************************************** Init3Regions** This is the procedure called by the object drawing routines* to get ready to clip to three aribrary regions.** The three regions	are already dereferenced and locked.  The* pointers are in RgnPtrA, RgnPtrB and RgnPtrC.** For each of the three regions, the procedure calls InitRgn* which sets up the	state record for the region.** Modifications:* 12/2/87      GCP	   Added InitUp3Rgns to handle cases where we*	   want to seek up through a region****************************************************************	EXPORT iInit3RegionsiInit3Regions	PROC*              using E0Vectors;---------------------------------------------------;; First I initialize NonRectRegions and	set up; MinX, MaxX and LeftH;	stz NonRectRegions	lda MinRect+2	sta MinX	lda MinRect+6	sta MaxX	lda BoundsRect+2	sta LeftH;---------------------------------------------------;; Now initialize each of the three state records.;	MoveLong RgnPtrA,RgnPtr	MoveLong ScanPtrA,ScanPtr	MoveLong StatePtrA,StatePtr	jsl InitRgn	MoveLong RgnPtrB,RgnPtr	MoveLong ScanPtrB,ScanPtr	MoveLong StatePtrB,StatePtr	jsl InitRgn	MoveLong RgnPtrC,RgnPtr	MoveLong ScanPtrC,ScanPtr	MoveLong StatePtrC,StatePtr	jsl InitRgn	rtl	ENDP	EXPORT InitUp3RgnsInitUp3Rgns	PROC*              using E0Vectors;---------------------------------------------------;; First I initialize NonRectRegions and	set up; MinX, MaxX and LeftH;	stz NonRectRegions	lda MinRect+2	sta MinX	lda MinRect+6	sta MaxX	lda BoundsRect+2	sta LeftH;---------------------------------------------------;; Now initialize each of the three state records.;	MoveLong RgnPtrA,RgnPtr	MoveLong ScanPtrA,ScanPtr	MoveLong StatePtrA,StatePtr	jsl InitRgnUp	MoveLong RgnPtrB,RgnPtr	MoveLong ScanPtrB,ScanPtr	MoveLong StatePtrB,StatePtr	jsl InitRgnUp	MoveLong RgnPtrC,RgnPtr	MoveLong ScanPtrC,ScanPtr	MoveLong StatePtrC,StatePtr	jsl InitRgnUp	rtl	ENDP****************************************************************** Seek3Regions** This is the procedure that builds the	scan line clip buffer* used by the slab and slice routines.** This buffer is made by combining three scan line clip buffers* for each of the three regions being clipped to.*****************************************************************	EXPORT iSeek3RegionsiSeek3Regions	PROC*              using RgnStateData*              using E0Vectors	stz BufChanged	; assume none change	MoveLong StatePtrA,StatePtr ; Seek along a	jsl SeekRgn	beq NoChangeA	inc BufChanged	; it changedNoChangeA	MoveLong StatePtrB,StatePtr ; Seek along B	jsl SeekRgn	beq NoChangeB	inc BufChanged	; it changedNoChangeB	MoveLong StatePtrC,StatePtr ; Seek along C	jsl SeekRgn	beq NoChangeC	inc BufChanged	; it changedNoChangeC	lda BufChanged	; did any change?	beq AllDone	; no, all done.;----------------------------------------------;; At least one changed so we have to rebuild; the master scanmask buffer.;	jsr JoinSetUp	jsl Join3BuffersAllDone	rtl	ENDP****************************************************************** Init2Regions** This is the procedure called by the object drawing routines* to get ready to clip to two aribrary regions.** The two regions are already dereferenced and locked.  The* pointers are in RgnPtrA and RgnPtrB.** For each region, the this procedure calls InitRgn* which sets up the	state record for the region.*****************************************************************	EXPORT iInit2RegionsiInit2Regions	PROC*              using E0Vectors;---------------------------------------------------;; First I initialize NonRectRegions and	set up; MinX, MaxX and LeftH;	stz NonRectRegions	lda MinRect+2	sta MinX	lda MinRect+6	sta MaxX	lda BoundsRect+2	sta LeftH;---------------------------------------------------;; Now initialize each of the two state records.;	MoveLong RgnPtrA,RgnPtr	MoveLong ScanPtrA,ScanPtr	MoveLong StatePtrA,StatePtr	jsl InitRgn	MoveLong RgnPtrB,RgnPtr	MoveLong ScanPtrB,ScanPtr	MoveLong StatePtrB,StatePtr	jsl InitRgn	rtl	ENDP****************************************************************** Seek2Regions** This is the procedure that builds the	scan line clip buffer* used by the slab and slice routines.** This buffer is made by combining scan	line clip buffers* for each of the two regions being clipped to.*****************************************************************	EXPORT iSeek2RegionsiSeek2Regions	PROC*              using RgnStateData*              using E0Vectors	stz BufChanged	; assume none change	MoveLong StatePtrA,StatePtr ; Seek along a	jsl SeekRgn	beq NoChangeA	inc BufChanged	; it changedNoChangeA	MoveLong StatePtrB,StatePtr ; Seek along B	jsl SeekRgn	beq NoChangeB	inc BufChanged	; it changedNoChangeB	lda BufChanged	; did any change?	beq AllDone	; no, all done.;----------------------------------------------;; At least one changed so we have to rebuild; the master scanmask buffer.;	jsr JoinSetUp	jsl Join2BuffersAllDone	rtl	ENDP****************************************************************** Init1Region** This is the procedure called by the object drawing routines* to get ready to clip to one aribtrary	region.** The region is already dereferenced and locked.  The* pointer is in RgnPtrA.*****************************************************************	EXPORT iInit1RegioniInit1Region	PROC*              using E0Vectors;---------------------------------------------------;; First I initialize NonRectRegions and	set up; MinX, MaxX and LeftH;	stz NonRectRegions	lda MinRect+2	sta MinX	lda MinRect+6	sta MaxX	lda BoundsRect+2	sta LeftH;---------------------------------------------------;; Now initialize the state record.;	MoveLong RgnPtrA,RgnPtr	MoveLong ScanPtrA,ScanPtr	MoveLong StatePtrA,StatePtr	jsl InitRgn	rtl	ENDP****************************************************************** Seek1Region** This is the procedure that builds the	scan line clip buffer* used by the slab and slice routines.** This buffer is made from the scan line clip buffer of* the region being clipped to.*****************************************************************	EXPORT iSeek1RegioniSeek1Region	PROC*              using RgnStateData*              using E0Vectors	MoveLong StatePtrA,StatePtr ; Seek along a	jsl SeekRgn	beq AllDone;----------------------------------------------;; It changed so we have to rebuild; the master scanmask buffer.;	jsr JoinSetup	jsl Join1BufferAllDone	rtl	ENDP****************************************************************** JoinSetUp** This routine sets	RFirstWord and RLastWord based on MinX,* MaxX and LeftH*****************************************************************	EXPORT JoinSetupJoinSetup	PROC	lda MinX	sec	sbc LeftH	lsr a	lsr a	lsr a	and #$FFFE	sta RFirstWord	lda MaxX	; Dec the max once	dec a	sec	sbc LeftH	lsr a	lsr a	lsr a	and #$FFFE	sta RLastWord	rts	ENDP;                copy regions/init.seek****************************************************************** InitRgn** The region to initialize is passed in	RgnPtr.* The state record to setup is passed in StatePtr.* The pointer to the Scan Buffer to use	is kept in ScanPtr.*****************************************************************	EXPORT iInitRgniInitRgn	PROC*              using RgnStateData	ldx MinX	; we do this for both types of	lda MaxX	; regions	jsr LineSetup	jsr ZeroScanBuf	lda [RgnPtr]	; now see if it is rect or bizzare	cmp #10	beq ItsRectangular	inc NonRectRegions	; set this flag for	later use	lda #$0000	; set this flag to 0	sta [StatePtr];              lda #$0000	;already set to zero	ldy #S_SeekDir	; Set for search down	sta [StatePtr],y	lda RgnPtr	; Set the RgnPtr in	the StateRec	ldy #S_RgnPtr	sta [StatePtr],y	lda RgnPtr+2	ldy #S_RgnPtr+2	sta [StatePtr],y	jsr InitDataPtr	; set the dataptr in the state rec	jsr SetBufStuff	lda #-MaxInt	; now put ThisV in state record	ldy #S_ThisV	sta [StatePtr],y	ldy #2	; NextV will be top	of bounding	lda [RgnPtr],y	; box	ldy #S_NextV	sta [StatePtr],y	lda MinX	; MinX, MaxX & LeftH	ldy #S_MinX	sta [StatePtr],y	lda MaxX	ldy #S_MaxX	sta [StatePtr],y	lda LeftH	ldy #S_LeftH	sta [StatePtr],y	rtlItsRectangular		; 	lda #$8000	; set this flag to 1	sta [StatePtr]	lda RFirstWord	ldy #S_LOffset	sta [StatePtr],y	lda RLeftMask	ldy #S_LMask	sta [StatePtr],y	lda RLastWord	ldy #S_ROffset	sta [StatePtr],y	lda RRightMask	ldy #S_RMask	sta [StatePtr],y	jsr SetBufStuff	ldy #2	; Set S_RgnTop to top of bounding rect	lda [RgnPtr],y	ldy #S_RgnTop	sta [StatePtr],y	ldy #6	; set RgnBot to bot	of bounding rect	lda [RgnPtr],y	ldy #S_RgnBot	sta [StatePtr],y	rtlSetBufStuff		; 	lda ScanPtr	; now put the pointer to scan buf	ldy #S_ScanBuf	; in state record	sta [StatePtr],y	lda ScanPtr+2	ldy #S_ScanBuf+2	sta [StatePtr],y	lda MaxWidth	; now put the buffer size in	ldy #S_ScanSize	sta [StatePtr],y	rts	ENDP****************************************************************** InitRgnUp** The region to initialize is passed in	RgnPtr.* The state record to setup is passed in StatePtr.* The pointer to the Scan Buffer to use	is kept in ScanPtr.*****************************************************************	EXPORT InitRgnUpInitRgnUp	PROC*              using RgnStateData	lda [RgnPtr]	; now see if it is rect or bizzare	cmp #10	bne NotRectang	jmp iInitRgn	;handle in the normal wayNotRectang	ldx MinX	; we do this for both types of	lda MaxX	; regions	jsr LineSetup	jsr ZeroScanBuf	inc NonRectRegions	; set this flag for	later use	lda #$0000	; set this flag to 0	sta [StatePtr]	lda #$FFFF	;	ldy #S_SeekDir	; Set for search down	sta [StatePtr],y	lda RgnPtr	; Set the RgnPtr in	the StateRec	ldy #S_RgnPtr	sta [StatePtr],y	lda RgnPtr+2	ldy #S_RgnPtr+2	sta [StatePtr],y	lda RgnPtr	; set the dataptr in the state rec	clc	adc [RgnPtr]	ldy #S_DataPtr	sta [StatePtr],y	lda RgnPtr+2	adc #0	ldy #S_DataPtr+2	sta [StatePtr],y	lda ScanPtr	; now put the pointer to scan buf	ldy #S_ScanBuf	; in state record	sta [StatePtr],y	lda ScanPtr+2	ldy #S_ScanBuf+2	sta [StatePtr],y	lda MaxWidth	; now put the buffer size in	ldy #S_ScanSize	sta [StatePtr],y	lda #MaxInt	; Start at the Bottom	ldy #S_ThisV	sta [StatePtr],y	ldy #S_currVpos	lda [RgnPtr]	dec a	dec a	sta [StatePtr],y	jsr GetNextV	lda MinX	; MinX, MaxX & LeftH	ldy #S_MinX	sta [StatePtr],y	lda MaxX	ldy #S_MaxX	sta [StatePtr],y	lda LeftH	ldy #S_LeftH	sta [StatePtr],y	rtl	ENDP********************************************************************************************************************************	EXPORT InitDataPtrInitDataPtr	PROC*              using RgnStateDATA	lda RgnPtr	; Set the DataPtr in the State Rec	clc	adc #10	ldy #s_DataPtr	sta [StatePtr],y	lda RgnPtr+2	adc #0	ldy #S_DataPtr+2	sta [StatePtr],y	rts	ENDP****************************************************************** ZeroScanBuf** This routine zeros a scan line buffer	from RFirstWord - 2	to* RLastWord (which were calculated by LineSetUp from MinX &* MinY.** I need to zero one word before in the	case of painting* pixels where the dest pointer was adjusted to be one word* less that it really needs to be.*****************************************************************	EXPORT ZeroScanBufZeroScanBuf	PROC	ldy RFirstWord	beq SkipBackup	dey	deySkipBackup	lda #0Loop	sta [ScanPtr],y	iny	iny	cpy RLastWord	bcc Loop	beq Loop	rts	ENDP****************************************************************** LineSetup** This is used by the Rectagular part of InitRgn and the* non rectangular part of SeekRgn.  The	Start and Stop Points* are passed in A and X.   X is the start, A is the stop*****************************************************************	EXPORT LineSetupLineSetup	PROC*              using RgnStateDATA	txy	; put this in y;	dec a	; we dec the stop point as usual;	sec	; Turn Local to scan coordinates	clc	; clear the carry to perform the dec a	sbc LeftH	tax	; save this value in x	lsr a	; make pixels into bytes by	lsr a	; dividing by 8	lsr a	and #$FFFE	; make this even to	mark word	sta RLastWord	; containing first pixel	txa	; get it back from x	and #15	asl a	tax	lda >RightBitMask,x	; Get appropriate mask	sta RRightMask	tya	; change coordinates	sec	sbc LeftH	tax	; save this value in x	lsr a	; make pixels into bytes by 8	lsr a	lsr a	and #$FFFE	sta RFirstWord	txa	; get it back from x	and #15	asl a	tax	lda >LeftBitMask,x	sta RLeftMask	rts	ENDP****************************************************************** Left Bit Mask Table** Note that the "b"	directive puts its inputs into mem as* a byte stream s the byte on the left is at a lower memory* loc than the byte	on the right.*****************************************************************	EXPORT LeftBitMaskLeftBitMask	PROC	DC.B %11111111,%11111111	DC.B %01111111,%11111111	DC.B %00111111,%11111111	DC.B %00011111,%11111111	DC.B %00001111,%11111111	DC.B %00000111,%11111111	DC.B %00000011,%11111111	DC.B %00000001,%11111111	DC.B %00000000,%11111111	DC.B %00000000,%01111111	DC.B %00000000,%00111111	DC.B %00000000,%00011111	DC.B %00000000,%00001111	DC.B %00000000,%00000111	DC.B %00000000,%00000011	DC.B %00000000,%00000001	ENDP****************************************************************** Right Bit Mask Table** Note that the "b"	directive puts its inputs into mem as* a byte stream s the byte on the left is at a lower memory* loc than the byte	on the right.*****************************************************************	EXPORT RightBitMaskRightBitMask	PROC	DC.B %10000000,%00000000 ; 0	DC.B %11000000,%00000000 ; 1	DC.B %11100000,%00000000 ; 2	DC.B %11110000,%00000000 ; 3	DC.B %11111000,%00000000 ; 4	DC.B %11111100,%00000000 ; 5	DC.B %11111110,%00000000 ; 6	DC.B %11111111,%00000000 ; 7	DC.B %11111111,%10000000 ; 8	DC.B %11111111,%11000000 ; 9	DC.B %11111111,%11100000 ; 10	DC.B %11111111,%11110000 ; 11	DC.B %11111111,%11111000 ; 12	DC.B %11111111,%11111100 ; 13	DC.B %11111111,%11111110 ; 14	DC.B %11111111,%11111111 ; 15	ENDP****************************************************************** SeekRgn** The state record for the region to seek is passed in StatePtr*****************************************************************	EXPORT iSeekRgniSeekRgn	PROC*              using RgnStateDATA	lda [StatePtr]	bpl NotRectangular	jmp ItsRectangular;----------------------------------------------;; Return very quickly if scanbuf is already; current.;NotRectangular		; 	ldy #S_SeekDir	lda [StatePtr],y	beq GoingDown	jmp GoingUPGoingDown	lda CurrentY	; if the current y is less than	ldy #S_ThisV	; ThisV then we have to reseek	cmp [StatePtr],y	; from top of region	bmi Restart	ldy #S_NextV	; if the current y is less than	cmp [StatePtr],y	; NextV then the scan buf does	bpl ItMustChange	jmp AllDone_NC	; not change!Restart		; 	ldy #s_RgnPtr	; get the pointer to the region	lda [StatePtr],y	; add 10 and put result in the	clc	; data pointer.	adc #10	tax	ldy #s_RgnPtr+2	lda [StatePtr],y	adc #0	ldy #s_DataPtr+2	sta [StatePtr],y	ldy #s_DataPtr	txa	sta [StatePtr],y	jsr GetStateInfo	; bring things down	to zp	ldx MinX	; set up to clear the scan buff	lda MaxX	;	jsr LineSetup	ldy #S_ScanBuf	lda [StatePtr],y	sta ScanPtr	ldy #S_ScanBuf+2	lda [StatePtr],y	sta ScanPtr+2	jsr ZeroScanBuf	bra JoinRest;----------------------------------------------;; Gosh, now I need to do something here.; I'll start by getting info I'll need from; the state record.;ItMustChange	jsr GetStateInfoJoinRest		; Down1	lda [DataPtr]	ldy #S_ThisV	; update ThisV	sta [StatePtr],y	BumpLongBy2 DataPtr	; bump the data ptr	twiceNextHor	lda [DataPtr]	; get left coord	cmp #MaxInt	beq EndOfLine	tax	; put left in x	IncLong DataPtr	IncLong DataPtr	lda [DataPtr]	; get right in a	IncLong DataPtr	IncLong DataPtr	cmp MinX	; if Right <= MinX then nexthor	bmi NextHor	beq NextHor	cpx MaxX	; if Left > MaxX then NextHor	bpl NextHor	cpx MinX	; if Left > MinX then LeftOK	bpl LeftOK	ldx MinXLeftOk	cmp MaxX	; if Right < MaxX then RightOK	bmi RightOK	lda MaxXRightOK	jsr LineSetUp	jsr InvertBuf	bra NextHorEndOfLine		; 	BumpLongBy2 DataPtr	; bump data ptr so points to the next v	lda [DataPtr]	; update nextV in State rec	ldy #s_NextV	sta [StatePtr],y	cmp CurrentY	; if NextV < CurrentY	beq DownAgain	bpl DoneNowDownAgain	jmp Down1DoneNow		; ;----------------------------------------------;; It's all done so update the data ptr in; the state record;	ldy #S_DataPtr	lda DataPtr	sta [StatePtr],y	ldy #S_DataPtr+2	lda DataPtr+2	sta [StatePtr],y	bra AllDone_CItsRectangular		; 	lda CurrentY	ldy #S_RgnTop	cmp [StatePtr],y	bmi Outside	ldy #S_RgnBot	cmp [StatePtr],y	bpl Outside	lda [StatePtr]	; this flag indicate if scan buf	and #1	; is already set	bne AllDone_NC	jsr RectScanInvert	lda [StatePtr]	ora #1	sta [StatePtr]	bra AllDone_COutSide	lda [StatePtr]	and #1	beq AllDone_NC	jsr RectScanInvert	lda [StatePtr]	and #$FFFE	sta [StatePtr]AllDone_C	rep #%00000010	; clear the z flag	rtlAllDone_NC	sep #%00000010	; set the z flag	rtlGoingUp		; 	lda CurrentY	; if the current y is less than	inc A	ldy #S_ThisV	; ThisV then we have to reseek	cmp [StatePtr],y	; from top of region	bpl RestU	beq RestU	ldy #S_NextV	; if the current y is less than	cmp [StatePtr],y	; NextV then the scan buf does	beq UpItMustChng	bmi UpItMustChng	jmp AllDone_NC	; not change!RestU		; ;              _sysbeep	ldy #S_MinX	lda [StatePtr],y	sta MinX	ldy #S_MaxX	lda [StatePtr],y	sta MaxX	ldy #S_LeftH	lda [StatePtr],y	sta LeftH	ldx MinX	; set up to clear the scan buff	lda MaxX	;	jsr LineSetup	ldy #S_ScanBuf	lda [StatePtr],y	sta ScanPtr	ldy #S_ScanBuf+2	lda [StatePtr],y	sta ScanPtr+2	jsr ZeroScanBuf	bra JoinRestU;----------------------------------------------;; Gosh, now I need to do something here.; I'll start by getting info I'll need from; the state record.;UpItMustChng		; 	ldy #S_MinX	lda [StatePtr],y	sta MinX	ldy #S_MaxX	lda [StatePtr],y	sta MaxX	ldy #S_LeftH	lda [StatePtr],y	sta LeftHJoinRestU		; UP1		; 	ldy #S_currVpos	lda [StatePtr],y	;get index into region	pha	;save for later	tay	lda [RgnPtr],y	;get current line number	ldy #S_ThisV	; update ThisV	sta [StatePtr],y	ply	;recover	iny	;index to first x	inyNextHorU	lda [RgnPtr],y	; get left coord	cmp #MaxInt	beq EndOfLineU	tax	; put left in x	iny	iny	;index to next x	lda [RgnPtr],y	; get right in a	iny	iny	cmp MinX	; if Right <= MinX then nexthor	bmi NextHorU	beq NextHorU	cpx MaxX	; if Left > MaxX then NextHor	bpl NextHorU	cpx MinX	; if Left > MinX then LeftOK	bpl LeftOKU	ldx MinXLeftOkU	cmp MaxX	; if Right < MaxX then RightOK	bmi RightOKU	lda MaxXRightOKU	phy	jsr LineSetUp	jsr InvertBuf	ply	bra NextHorUEndOfLineU		; 	ldy #S_currVpos	lda [StatePtr],y	tay	lda [RgnPtr],y	ldy #S_ThisV	sta [StatePtr],y	jsr GetNextV	;Gets the next v	ldy #S_currVpos	lda [StatePtr],y	; index to next line number	tay	lda [RgnPtr],y	ldy #s_NextV	sta [StatePtr],y	dec a	cmp CurrentY	; if NextV < CurrentY	bmi DoneNowUUPAgain	jmp UP1DoneNowU	jmp DoneNow	ENDP****************************************************************** GetStateInfo** This is a routine	shared by alternative paths through* SeekRgn.  It pulls necessary info out	of the state record* and puts them on zero page.*****************************************************************	EXPORT GetStateInfoGetStateInfo	PROC*              using RgnStateDATA	ldy #S_MinX	lda [StatePtr],y	sta MinX	ldy #S_MaxX	lda [StatePtr],y	sta MaxX	ldy #S_LeftH	lda [StatePtr],y	sta LeftH	ldy #S_DataPtr	lda [StatePtr],y	sta DataPtr	ldy #S_DataPtr+2	lda [StatePtr],y	sta DataPtr+2	rts	ENDP****************************************************************** RectScanInvert** This is a fast inverter for the scan line buff optimizing* for rectangular region.*****************************************************************	EXPORT RectScanInvertRectScanInvert	PROC*              using RgnStateDATA	ldy #S_LOffset	lda [StatePtr],y	sta RFirstWord	ldy #S_LMask	lda [StatePtr],y	; get left mask	sta RLeftMask	ldy #S_ROffset	lda [StatePtr],y	; get right offset	sta RLastWord	ldy #S_RMask	lda [StatePtr],y	; get right mask	sta RRightMask	EXPORT InvertBufInvertBuf		;       	phb	; save the data bank reg	ldy #S_ScanBuf	lda [StatePtr],y	sta ScanPtr	phb	; dummy byte on stack	iny	lda [StatePtr],y	; get high byte of 3 byte ptr	sta 0,s	; overstore dummy	plb	; set b	jsr SpecialSlab	plb	; restore data bank	reg	rts	ENDP*******************************************************************  GetNextV*      This routine	searches from the present Yn. An Index into*      the region description (currVpos) is used to keep track*      of the position of the active line of the region.****  Inputs: none**  Outputs: none**  Side effects: Sets currVpos in region state record to the index for the*          next line.******************************************************************	EXPORT GetNextVGetNextV	PROC*          using RgnStateData	ldy #S_currVpos	;Get index to the current Yn	lda [StatePtr],y	tay	dey	;Start by bumping the index to point to	dey	;the end of the previous line.sloop	cpy #10	;are we already into the rect desc?	bmi done	dey	;point to Xn	dey	lda [RgnPtr],y	cmp #Maxint	;is it the end of the next line?	bne sloop	;nope, gotta go up one one more.done	iny	;point to Yn	iny	lda [RgnPtr],y	;get line number	tyx	;save index	ldy #S_NextV	sta [StatePtr],y	;save next line	txa	;recover index	ldy #S_currVpos	sta [StatePtr],y;          ldy     #S_DataIndex;          sta     [StatePtr],y	rts	ENDP;                copy regions/special.slab****************************************************************** SpecialSlab** All the slab routines use the same data on zero page. This* one is no different.** Before any slab routine is called, the data bank register* is set to the bank containing the pixel map.** The following are	set up on zero page	before this routine* is called:** Inputs:**    RLeftMask	The Pixels not being touched on the left are*                  set to zero in this word mask.**    RRightMask	The Pixels not being touched on the right are*                  set to zero in this word mask**    RFirstWord	The First word on the scan line to deal	with**    RLastWord	The last word on the scan line to deal with**    ScanPtr       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**** Variables**    None** 2/1/89	Mensch*	Optimized to use a table offset aproach to this action** 3/1/89	Mensch* Removed optimizations, this routine is not called often enough to warrant* an additional 1024 bytes in ROM and patch file.*****************************************************************	EXPORT SpecialSlabSpecialSlab	PROCMaxInRow	equ 80*              using CoreData	lda RLeftMask	ldy RFirstWord	cpy RLastWord	bcc MultiWords	and RRightMask	; one word only--combine masksMultiWords		; 	eor (ScanPtr),y	sta (ScanPtr),y	bra IncCntrsNextWord	lda #$FFFF	eor (ScanPtr),y	sta (ScanPtr),y	; put it in destIncCntrs	iny	iny	cpy RLastWord	bcc NextWord	bne AllDone	; was only one word	lda RRightMask	eor (ScanPtr),y	sta (ScanPtr),yAllDone	rts	ENDP****************************************************************;                copy regions/join.buffers****************************************************************** Join3Buffers** This takes the three 1-bit per pixel scan line buffers,* ANDs them together and expands them to n-bits per pixel* based on the PortSCB.** This routine assumes that the four buffers are all in the * same bank!*****************************************************************	EXPORT iJoin3BuffersiJoin3Buffers	PROC	bit PortSCB-1	bpl Mode320	ldy RFirstWord	; backup up twice unless it is	beq Loop640	; zero	dey	deyLoop640	lda [ScanPtrA],y	; merge the three	and [ScanPtrB],y	and [ScanPtrC],y	jsr Expand640	cpy RLastWord	bcc Loop640	; continue until greater than	beq Loop640	bra AllDoneMode320		; 	ldy RFirstWord	; backup 2 unless zero	beq Loop320	dey	deyLoop320	lda [ScanPtrA],y	; merge the three	and [ScanPtrB],y	and [ScanPtrC],y	jsr Expand320	cpy RLastWord	bcc Loop320	; continue until greater than	beq Loop320AllDone		; 	rtl	ENDP****************************************************************** Join2Buffers** This takes two 1-bit per pixel scan line buffers,	  * ANDs them together and expands them to n-bits per pixel* based on the PortSCB.** This routine assumes that the four buffers are all in the * same bank!*****************************************************************	EXPORT iJoin2BuffersiJoin2Buffers	PROC	bit PortSCB-1	bpl Mode320	ldy RFirstWord	; backup 2 unless zero	beq Loop640	dey	deyLoop640	lda [ScanPtrA],y	; merge the two	and [ScanPtrB],y	jsr Expand640	cpy RLastWord	bcc Loop640	; continue until greater than	beq Loop640	bra AllDoneMode320		; 	ldy RFirstWord	; backup 2 unless zero	beq loop320	dey	deyLoop320	lda [ScanPtrA],y	; merge the two	and [ScanPtrB],y	jsr Expand320	cpy RLastWord	bcc Loop320	; continue until greater than	beq Loop320AllDone		; 	rtl	ENDP****************************************************************** Join1Buffers** This takes one 1-bit per pixel scan line buffer,* and expands it to	n-bits per pixel based on the PortSCB.** This routine assumes that the four buffers are all in the * same bank!*****************************************************************	EXPORT iJoin1BufferiJoin1Buffer	PROC	bit PortSCB-1	bpl Mode320	ldy RFirstWord	; backup 2 unless zero	beq loop640	dey	deyLoop640	lda [ScanPtrA],y	; expand the one	jsr Expand640	cpy RLastWord	bcc Loop640	; continue until greater than	beq Loop640	bra AllDoneMode320		; 	ldy RFirstWord	; backup 2 unless zero	beq loop320	dey	deyLoop320	lda [ScanPtrA],y	; expand the one	jsr Expand320	cpy RLastWord	bcc Loop320	; continue until greater than	beq Loop320AllDone		; 	rtl	ENDP****************************************************************** Expand640** This expands the word in a from 16 1-bit pixels to two* words of 16 2-bit	pixels and puts them in the ScanMaskRef* starting at a value represented by Y*****************************************************************	EXPORT Expand640Expand640	PROC	pha	; save on stack	and #$00FF	; deal only with one byte at at time	asl a	; double value so can index into	tax	; conversion table	lda >ConTable640,x	tax	; save this in x	tya	; get y in a so can	double it	asl a	; and it becomes index into chunky	tay	; buffer.	txa	; get what to store	back from x	sta [ScanMaskRef],y	; store it	pla	; now get original merged word off stack	xba	; get the high byte	in low	and #$00FF	; and now we'll work with it	asl a	; double so it is index into con table	tax	lda >ConTable640,x	iny	; bump y so it points to new word in	iny	; chunky buffer	sta [ScanMaskRef],y	; store it	tya	; halve index so can point to small	lsr a	; buffer again.	tay	iny	; bump once (already bumped second time	rts	ENDP****************************************************************** Expand620** This expands the word in a from 16 1-bit pixels to four* words of 16 4-bit	pixels and puts them in the ScanMaskRef* starting at a value represented by Y*****************************************************************	EXPORT Expand320Expand320	PROC	pha	; save on stack	and #$00FF	; deal only with one byte at at time	asl a	; quadruple value so can index into	asl a	; convertion table	tax	lda >ConTable320+2,x	pha	lda >ConTable320,x	tax	; save this in x	tya	; get y in a so can	mult by 4	asl a	; and it becomes index into chunky	asl a	; buffer	tay	; Now back to Y	txa	; get what to store	back from x	sta [ScanMaskRef],y	; store it	iny	iny	pla	sta [ScanMaskRef],y	pla	; now get original merged word off stack	xba	; get the high byte	in low	and #$00FF	; and now we'll work with it	asl a	; Quadruple so it is index into	asl a	; conversion table	tax	lda >ConTable320+2,x	pha	lda >ConTable320,x	iny	; bump y so it points to new word in	iny	; chunky buffer	sta [ScanMaskRef],y	; store it	iny	iny	pla	sta [ScanMaskRef],y	iny	; bump 2 more times	so after div by 4	iny	; index to 1-bit is	bumped twice.	tya	; quarter index so can point to small	lsr a	; buffer again.	lsr a	tay	rts	ENDP;                copy regions/table.320	EXPORT ConTable320ConTable320	PROC	DC.B $00,$00,$00,$00 ; 00000000	DC.B $00,$00,$00,$0F ; 00000001	DC.B $00,$00,$00,$F0 ; 00000010	DC.B $00,$00,$00,$FF ; 00000011	DC.B $00,$00,$0F,$00 ; 00000100	DC.B $00,$00,$0F,$0F ; 00000101	DC.B $00,$00,$0F,$F